//           |  head 3 : 32 rows          (warps 6,7)         |
//           +------------------------------------------------+
//
// Every warp keeps a 16 x 128 score tile and a 16 x 128 output tile in
// registers, and streams 128 wide K/V tiles through shared memory with a two
// stage cp.async pipeline.  The online softmax stores the running maximum in
// the log2 domain so a weight is one fma plus one ex2.

#include <torch/extension.h>

#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>

#include <cmath>
#include <cstdint>

