    80	__device__ __forceinline__ void ldsm_x4_t(uint32_t (&d)[4], const void* addr) {
    81	    uint32_t a = (uint32_t)__cvta_generic_to_shared(addr);
    82	    asm volatile("ldmatrix.sync.aligned.m8n8.x4.trans.shared.b16 {%0,%1,%2,%3}, [%4];\n"
    83	                 : "=r"(d[0]), "=r"(d[1]), "=r"(d[2]), "=r"(d[3])
    84	                 : "r"(a));
    85	}
    86	
    87	__device__ __forceinline__ void cp_async16(void* dst, const void* src) {
    88	    uint32_t d = (uint32_t)__cvta_generic_to_shared(dst);
    89	    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" ::"r"(d), "l"(src));
    90	}
    91	
    92	__device__ __forceinline__ void cp_commit() { asm volatile("cp.async.commit_group;\n"); }
    93	
    94	template <int kN>
    95	__device__ __forceinline__ void cp_wait() {
    96	    asm volatile("cp.async.wait_group %0;\n" ::"n"(kN));
    97	}
    98	
    99	// Hardware exp2.  Two ulp of a softmax weight is far inside the bf16 contract.
   100	__device__ __forceinline__ float ex2(float x) {
   101	    float y;
   102	    asm("ex2.approx.f32 %0, %1;\n" : "=f"(y) : "f"(x));
   103	    return y;
   104	}
   105	
   106	__device__ __forceinline__ uint32_t pack_bf16(float lo, float hi) {
   107	    __nv_bfloat162 h = __floats2bfloat162_rn(lo, hi);
   108	    return *reinterpret_cast<uint32_t*>(&h);
   109	}
   110	
   111	// --------------------------------------------------------------- addresses ---
   112	// B of Q*K^T: K is [kv][dim] row major, which already is the column major
   113	// 16x8 fragment.  r0/r1 load the low k half of one k step, r2/r3 the next.
   114	__device__ __forceinline__ const __nv_bfloat16* k_frag_addr(const __nv_bfloat16* tile,
   115	                                                            int nblk, int ks, int lane) {
   116	    const int row = nblk * 8 + (lane & 7);
   117	    const int col = ks * 16 + ((lane >> 3) & 1) * 8 + (lane >> 4) * 16;
   118	    return tile + row * kSmemStride + col;
   119	}
   120	
   121	// B of P*V: V is [kv][dim], so the fragment needs the transposing load.  One
   122	// x4 covers one k step and two dim blocks.
   123	__device__ __forceinline__ const __nv_bfloat16* v_frag_addr(const __nv_bfloat16* tile,
   124	                                                            int ks, int nd, int lane) {
   125	    const int row = ks * 16 + (lane & 7) + ((lane >> 3) & 1) * 8;
   126	    const int col = nd * 8 + (lane >> 4) * 8;
   127	    return tile + row * kSmemStride + col;
   128	}
   129	
   130	// ---------------------------------------------------------------- load tile ---
   131	// A K or V tile is 128 rows x 128 dims = 16B chunks, 8 per thread.
   132	__device__ __forceinline__ void load_kv_tile(const __nv_bfloat16* __restrict__ src,
   133	                                             __nv_bfloat16* dst, int tid) {
   134	    const char* g = reinterpret_cast<const char*>(src);
   135	    char* s       = reinterpret_cast<char*>(dst);
   136	#pragma unroll
   137	    for (int i = 0; i < 8; ++i) {
   138	        const int chunk = tid + i * kThreads;   // 0 .. 2047
   139	        const int row   = chunk >> 4;           // 16 chunks per row
   140	        const int col   = (chunk & 15) * 16;    // byte offset inside the row
   141	        cp_async16(s + row * (kSmemStride * 2) + col,
   142	                   g + (size_t)row * (kKVRowStride * 2) + col);
   143	    }
   144	}
   145	
   146	// --------------------------------------------------------------- main loop ---
   147	// Consumes one K/V tile pair and folds it into the online softmax.
   148	__device__ __forceinline__ void attend_tile(const __nv_bfloat16* kt,
   149	                                            const __nv_bfloat16* vt,
   150	                                            const uint32_t (&qfrag)[8][4],
   151	                                            float (&acc)[kNB][4], float (&mstat)[2],
   152	                                            float (&lstat)[2], bool diagonal,
   153	                                            int lim0, int c0) {
   154	    const int lane = threadIdx.x & 31;
   155	
   156	    // ---- S = Q * K^T ----
   157	    float s[kNB][4];
   158	#pragma unroll
   159	    for (int nb = 0; nb < kNB; ++nb) {
   160	        s[nb][0] = s[nb][1] = s[nb][2] = s[nb][3] = 0.f;
   161	    }
   162	#pragma unroll
   163	    for (int nb = 0; nb < kNB; ++nb) {
   164	#pragma unroll
   165	        for (int ks = 0; ks < 8; ks += 2) {
   166	            uint32_t bf[4];
   167	            ldsm_x4(bf, k_frag_addr(kt, nb, ks, lane));
   168	            mma_bf16(s[nb], qfrag[ks], bf[0], bf[1]);
   169	            mma_bf16(s[nb], qfrag[ks + 1], bf[2], bf[3]);
   170	        }
   171	    }
   172	
   173	    // ---- causal mask, only on the tile that straddles the diagonal ----
   174	    if (diagonal) {
   175	#pragma unroll
   176	        for (int nb = 0; nb < kNB; ++nb) {
   177	            const int c = nb * 8 + c0;
   178	            s[nb][0] = (c <= lim0) ? s[nb][0] : -INFINITY;
   179	            s[nb][1] = (c + 1 <= lim0) ? s[nb][1] : -INFINITY;
   180	            s[nb][2] = (c <= lim0 + 8) ? s[nb][2] : -INFINITY;
   181	            s[nb][3] = (c + 1 <= lim0 + 8) ? s[nb][3] : -INFINITY;
   182	        }
   183	    }
   184	
   185	    // ---- row statistics: pairwise tree keeps the chain short ----
   186	    float rmax0[kNB / 2], rmax1[kNB / 2];
   187	#pragma unroll
   188	    for (int i = 0; i < kNB / 2; ++i) {
   189	        rmax0[i] = fmaxf(fmaxf(s[2 * i][0], s[2 * i][1]),
   190	                         fmaxf(s[2 * i + 1][0], s[2 * i + 1][1]));
   191	        rmax1[i] = fmaxf(fmaxf(s[2 * i][2], s[2 * i][3]),
   192	                         fmaxf(s[2 * i + 1][2], s[2 * i + 1][3]));
   193	    }
   194	#pragma unroll
   195	    for (int i = 0; i < kNB / 4; ++i) {
   196	        rmax0[i] = fmaxf(rmax0[2 * i], rmax0[2 * i + 1]);
   197	        rmax1[i] = fmaxf(rmax1[2 * i], rmax1[2 * i + 1]);
   198	    }
   199	#pragma unroll
   200	    for (int i = 0; i < 2; ++i) {
   201	        rmax0[i] = fmaxf(rmax0[2 * i], rmax0[2 * i + 1]);
   202	        rmax1[i] = fmaxf(rmax1[2 * i], rmax1[2 * i + 1]);
   203	    }
   204	    float rm0 = fmaxf(rmax0[0], rmax0[1]);
   205	    float rm1 = fmaxf(rmax1[0], rmax1[1]);
   206	    rm0 = fmaxf(rm0, __shfl_xor_sync(kFull, rm0, 1));
   207	    rm0 = fmaxf(rm0, __shfl_xor_sync(kFull, rm0, 2));
   208	    rm1 = fmaxf(rm1, __shfl_xor_sync(kFull, rm1, 1));
   209	    rm1 = fmaxf(rm1, __shfl_xor_sync(kFull, rm1, 2));
   210	
   211	    const float m2a = rm0 * kScaleL2e;
   212	    const float m2b = rm1 * kScaleL2e;
   213	    const float nm0 = fmaxf(mstat[0], m2a);
   214	    const float nm1 = fmaxf(mstat[1], m2b);
   215	    const float alpha0 = ex2(mstat[0] - nm0);
   216	    const float alpha1 = ex2(mstat[1] - nm1);
   217	    mstat[0] = nm0;
   218	    mstat[1] = nm1;
   219	
   220	    // Rescaling is a no-op whenever the running maximum did not move, which is
   221	    // the common case; skipping it saves 64 multiplies per tile.
   222	    if (alpha0 != 1.f) {
   223	#pragma unroll
   224	        for (int nb = 0; nb < kNB; ++nb) {
   225	            acc[nb][0] *= alpha0;
   226	            acc[nb][1] *= alpha0;
   227	        }
   228	    }
   229	    if (alpha1 != 1.f) {
   230	#pragma unroll
   231	        for (int nb = 0; nb < kNB; ++nb) {
   232	            acc[nb][2] *= alpha1;
   233	            acc[nb][3] *= alpha1;
   234	        }
   235	    }
   236	
   237	    // ---- weights and row sums ----
   238	    float rsum0[kNB / 2], rsum1[kNB / 2];
   239	#pragma unroll
   240	    for (int i = 0; i < kNB / 2; ++i) {
   241	        const float p0 = ex2(fmaf(s[2 * i][0], kScaleL2e, -nm0));
   242	        const float p1 = ex2(fmaf(s[2 * i][1], kScaleL2e, -nm0));
   243	        const float p2 = ex2(fmaf(s[2 * i][2], kScaleL2e, -nm1));
   244	        const float p3 = ex2(fmaf(s[2 * i][3], kScaleL2e, -nm1));
   245	        const float q0 = ex2(fmaf(s[2 * i + 1][0], kScaleL2e, -nm0));
   246	        const float q1 = ex2(fmaf(s[2 * i + 1][1], kScaleL2e, -nm0));
   247	        const float q2 = ex2(fmaf(s[2 * i + 1][2], kScaleL2e, -nm1));
   248	        const float q3 = ex2(fmaf(s[2 * i + 1][3], kScaleL2e, -nm1));
   249	        s[2 * i][0] = p0;
   250	        s[2 * i][1] = p1;
   251	        s[2 * i][2] = p2;
   252	        s[2 * i][3] = p3;
   253	        s[2 * i + 1][0] = q0;
   254	        s[2 * i + 1][1] = q1;
   255	        s[2 * i + 1][2] = q2;
   256	        s[2 * i + 1][3] = q3;
   257	        rsum0[i] = (p0 + p1) + (q0 + q1);
   258	        rsum1[i] = (p2 + p3) + (q2 + q3);
   259	    }
   260	#pragma unroll
   261	    for (int i = 0; i < kNB / 4; ++i) {
   262	        rsum0[i] = rsum0[2 * i] + rsum0[2 * i + 1];
   263	        rsum1[i] = rsum1[2 * i] + rsum1[2 * i + 1];
   264	    }
   265	#pragma unroll
   266	    for (int i = 0; i < 2; ++i) {
   267	        rsum0[i] = rsum0[2 * i] + rsum0[2 * i + 1];
   268	        rsum1[i] = rsum1[2 * i] + rsum1[2 * i + 1];
   269	    }
   270	    float rs0 = rsum0[0] + rsum0[1];
   271	    float rs1 = rsum1[0] + rsum1[1];
   272	    rs0 += __shfl_xor_sync(kFull, rs0, 1);
   273	    rs0 += __shfl_xor_sync(kFull, rs0, 2);
   274	    rs1 += __shfl_xor_sync(kFull, rs1, 1);
   275	    rs1 += __shfl_xor_sync(kFull, rs1, 2);
   276	    lstat[0] = lstat[0] * alpha0 + rs0;
   277	    lstat[1] = lstat[1] * alpha1 + rs1;
   278	
   279	    // ---- P (bf16 A operand of P * V) packed inside the P * V mma loop ----
   280	#pragma unroll
   281	    for (int ks = 0; ks < 8; ++ks) {
   282	        const uint32_t pfrag[4] = {pack_bf16(s[2 * ks][0], s[2 * ks][1]),
   283	                                   pack_bf16(s[2 * ks][2], s[2 * ks][3]),
   284	                                   pack_bf16(s[2 * ks + 1][0], s[2 * ks + 1][1]),
   285	                                   pack_bf16(s[2 * ks + 1][2], s[2 * ks + 1][3])};
   286	#pragma unroll
   287	        for (int nd = 0; nd < kNB; nd += 2) {
   288	            uint32_t bf[4];
   289	            ldsm_x4_t(bf, v_frag_addr(vt, ks, nd, lane));
   290	            mma_bf16(acc[nd], pfrag, bf[0], bf[1]);
   291	            mma_bf16(acc[nd + 1], pfrag, bf[2], bf[3]);
   292	        }
   293	    }
   294	}
   295	
   296	__global__ void __launch_bounds__(kThreads, 1)
   297	gqa_kernel(const __nv_bfloat16* __restrict__ q, const __nv_bfloat16* __restrict__ k,
   298	           const __nv_bfloat16* __restrict__ v, __nv_bfloat16* __restrict__ o,
   299	           const int seq, const int qblocks) {
   300	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
   301	    extern __shared__ __nv_bfloat16 smem[];
   302	    __nv_bfloat16* kbuf[kStages] = {smem, smem + kTileElems};
   303	    __nv_bfloat16* vbuf[kStages] = {smem + 2 * kTileElems, smem + 3 * kTileElems};
   304	
   305	    const int tid  = threadIdx.x;
   306	    const int lane = tid & 31;
   307	    const int warp = tid >> 5;
   308	
   309	    const int grp = blockIdx.x / qblocks;                  // kv head
   310	    const int qb  = qblocks - 1 - (blockIdx.x % qblocks);  // long CTAs launch first
   311	    const int q0  = qb * kRowsHead;
   312	    const int kvl = (q0 + kRowsHead - 1) >> 7;             // last kv tile (causal)
   313	
   314	    const int head = warp / kWarpsHead;
   315	    const int sub  = warp % kWarpsHead;
   316	    const int hq   = grp * kGroup + head;
   317	    const int row0 = q0 + sub * kTileRows;   // the 4 heads share the same rows
   318	
   319	    // ---- gather the 16x128 Q fragments straight into registers ----
   320	    const __nv_bfloat16* qrow = q + ((size_t)row0 * kHeadsQ + hq) * kDim;
   321	    const int lr = lane >> 2;                       // 0..7
   322	    const int c0 = (lane & 3) * 2;                  // 0,2,4,6
   323	    uint32_t qfrag[8][4];
   324	#pragma unroll
   325	    for (int ks = 0; ks < 8; ++ks) {
   326	        const __nv_bfloat16* p = qrow + ks * 16;
   327	        qfrag[ks][0] = *reinterpret_cast<const uint32_t*>(p + lr * kQRowStride + c0);
   328	        qfrag[ks][1] = *reinterpret_cast<const uint32_t*>(p + (lr + 8) * kQRowStride + c0);
   329	        qfrag[ks][2] = *reinterpret_cast<const uint32_t*>(p + lr * kQRowStride + c0 + 8);
   330	        qfrag[ks][3] =
   331	            *reinterpret_cast<const uint32_t*>(p + (lr + 8) * kQRowStride + c0 + 8);
   332	    }
   333	
   334	    float acc[kNB][4];
   335	#pragma unroll
   336	    for (int i = 0; i < kNB; ++i) {
   337	        acc[i][0] = acc[i][1] = acc[i][2] = acc[i][3] = 0.f;
   338	    }
   339	    float mstat[2] = {-INFINITY, -INFINITY};   // running max, log2 domain
   340	    float lstat[2] = {0.f, 0.f};               // running weight sum
   341	
   342	    const __nv_bfloat16* kg = k + grp * kDim;   // this CTA's kv head
   343	    const __nv_bfloat16* vg = v + grp * kDim;
   344	
   345	    load_kv_tile(kg, kbuf[0], tid);
   346	    load_kv_tile(vg, vbuf[0], tid);
   347	    cp_commit();
   348	
   349	    for (int j = 0; j <= kvl; ++j) {
   350	        const int buf = j & 1;
   351	        if (j > 0) cp_wait<1>();   // tile j is in shared memory for this thread
   352	        __syncthreads();           // ... and for every other warp; buffers are free
   353	        if (j < kvl) {             // prefetch the next tile into the idle buffer
   354	            load_kv_tile(kg + (size_t)(j + 1) * kBlockN * kKVRowStride, kbuf[buf ^ 1], tid);
   355	            load_kv_tile(vg + (size_t)(j + 1) * kBlockN * kKVRowStride, vbuf[buf ^ 1], tid);
   356	            cp_commit();
   357	        }
   358	
   359	        attend_tile(kbuf[buf], vbuf[buf], qfrag, acc, mstat, lstat, j == kvl,
   360	                    row0 + lr - j * kBlockN, c0);
   361	    }
   362	    cp_wait<0>();
   363	
   364	    // ---- normalise and store ----
   365	    const float inv0 = 1.f / lstat[0];
   366	    const float inv1 = 1.f / lstat[1];
   367	    __nv_bfloat16* orow = o + ((size_t)row0 * kHeadsQ + hq) * kDim;
   368	#pragma unroll
   369	    for (int nd = 0; nd < kNB; ++nd) {
   370	        __nv_bfloat162 lo = __floats2bfloat162_rn(acc[nd][0] * inv0, acc[nd][1] * inv0);
   371	        __nv_bfloat162 hi = __floats2bfloat162_rn(acc[nd][2] * inv1, acc[nd][3] * inv1);
   372	        *reinterpret_cast<__nv_bfloat162*>(orow + lr * kQRowStride + nd * 8 + c0) = lo;
   373	        *reinterpret_cast<__nv_bfloat162*>(orow + (lr + 8) * kQRowStride + nd * 8 + c0) = hi;
   374	    }
   375	#endif  // __CUDA_ARCH__ >= 800
   376	}
