   378	// ------------------------------------------------------------------- host ---
   379	void launch(const torch::Tensor& q, const torch::Tensor& k, const torch::Tensor& v,
   380	            torch::Tensor& o) {
   381	    TORCH_CHECK(q.is_cuda() && k.is_cuda() && v.is_cuda() && o.is_cuda(),
   382	                "gqa: inputs must be CUDA tensors");
   383	    TORCH_CHECK(q.scalar_type() == at::kBFloat16 && k.scalar_type() == at::kBFloat16 &&
   384	                    v.scalar_type() == at::kBFloat16 && o.scalar_type() == at::kBFloat16,
   385	                "gqa: expected bfloat16 tensors");
   386	    TORCH_CHECK(q.is_contiguous() && k.is_contiguous() && v.is_contiguous() &&
   387	                    o.is_contiguous(),
   388	                "gqa: expected contiguous tensors");
   389	
   390	    const int64_t seq = q.size(1);
   391	    TORCH_CHECK(q.dim() == 4 && q.size(0) == 1 && q.size(2) == kHeadsQ &&
   392	                    q.size(3) == kDim,
   393	                "gqa: unexpected q shape");
   394	    TORCH_CHECK(k.sizes() == v.sizes() && k.size(0) == 1 && k.size(1) == seq &&
   395	                    k.size(2) == kHeadsKV && k.size(3) == kDim,
   396	                "gqa: unexpected k/v shape");
   397	    TORCH_CHECK(o.sizes() == q.sizes(), "gqa: unexpected o shape");
   398	    TORCH_CHECK(seq % kRowsHead == 0, "gqa: sequence must be a multiple of 32");
   399	
   400	    const at::cuda::CUDAGuard guard(q.device());
   401	    cudaStream_t stream = at::cuda::getCurrentCUDAStream(q.get_device()).stream();
   402	
   403	    static bool configured = false;
   404	    if (!configured) {
   405	        cudaFuncSetAttribute(gqa_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize,
   406	                             kSmemBytes);
   407	        configured = true;
   408	    }
   409	
   410	    const int qblocks = (int)(seq / kRowsHead);
   411	    gqa_kernel<<<qblocks * kHeadsKV, kThreads, kSmemBytes, stream>>>(
   412	        reinterpret_cast<const __nv_bfloat16*>(q.data_ptr<at::BFloat16>()),
   413	        reinterpret_cast<const __nv_bfloat16*>(k.data_ptr<at::BFloat16>()),
   414	        reinterpret_cast<const __nv_bfloat16*>(v.data_ptr<at::BFloat16>()),
   415	        reinterpret_cast<__nv_bfloat16*>(o.data_ptr<at::BFloat16>()), (int)seq, qblocks);
   416	    C10_CUDA_CHECK(cudaGetLastError());
   417	}
   418	
   419	}  // namespace
   420	
   421	void kernel(const torch::Tensor& q, const torch::Tensor& k, const torch::Tensor& v,
   422	            torch::Tensor& o) {
   423	    launch(q, k, v, o);
   424	}
