__device__ __forceinline__ void cp_commit() { asm volatile("cp.async.commit_group;\n"); }

template <int kN>
__device__ __forceinline__ void cp_wait() {
    asm volatile("cp.async.wait_group %0;\n" ::"n"(kN));
}

// Hardware exp2.  Two ulp of a softmax weight is far inside the bf16 contract.
__device__ __forceinline__ float ex2(float x) {
    float y;
    asm("ex2.approx.f32 %0, %1;\n" : "=f"(y) : "f"(x));
    return y;
}

__device__ __forceinline__ uint32_t pack_bf16(float lo, float hi) {
    __nv_bfloat162 h = __floats2bfloat162_rn(lo, hi);
    return *reinterpret_cast<uint32_t*>(&h);
}

// --------------------------------------------------------------- addresses ---
// B of Q*K^T: K is [kv][dim] row major, which already is the column major
// 16x8 fragment.  r0/r1 load the low k half of one k step, r2/r3 the next.
__device__ __forceinline__ const __nv_bfloat16* k_frag_addr(const __nv_bfloat16* tile,
                                                            int nblk, int ks, int lane) {
    const int row = nblk * 8 + (lane & 7);
    const int col = ks * 16 + ((lane >> 3) & 1) * 8 + (lane >> 4) * 16;
    return tile + row * kSmemStride + col;
}

// B of P*V: V is [kv][dim], so the fragment needs the transposing load.  One
// x4 covers one k step and two dim blocks.
__device__ __forceinline__ const __nv_bfloat16* v_frag_addr(const __nv_bfloat16* tile,
                                                            int ks, int nd, int lane) {
    const int row = ks * 16 + (lane & 7) + ((lane >> 3) & 1) * 8;
    const int col = nd * 8 + (lane >> 4) * 8;
    return tile + row * kSmemStride + col;
}

// ---------------------------------------------------------------- load tile ---
// A K or V tile is 128 rows x 128 dims = 16B chunks, 8 per thread.
__device__ __forceinline__ void load_kv_tile(const __nv_bfloat16* __restrict__ src,
                                             __nv_bfloat16* dst, int tid) {
    const char* g = reinterpret_cast<const char*>(src);
    char* s       = reinterpret_cast<char*>(dst);
#pragma unroll
    for (int i = 0; i < 8; ++i) {
        const int chunk = tid + i * kThreads;   // 0 .. 2047
        const int row   = chunk >> 4;           // 16 chunks per row
        const int col   = (chunk & 15) * 16;    // byte offset inside the row
        cp_async16(s + row * (kSmemStride * 2) + col,
                   g + (size_t)row * (kKVRowStride * 2) + col);
    }
}

// --------------------------------------------------------------- main loop ---
// Consumes one K/V tile pair and folds it into the online softmax.
__device__ __forceinline__ void attend_tile(const __nv_bfloat16* kt,
                                            const __nv_bfloat16* vt,
                                            const uint32_t (&qfrag)[8][4],
                                            float (&acc)[kNB][4], float (&mstat)[2],
                                            float (&lstat)[2], bool diagonal,
                                            int lim0, int c0) {
    const int lane = threadIdx.x & 31;

    // ---- S = Q * K^T ----
    float s[kNB][4];
#pragma unroll
