constexpr int kHeadsKV = 8;
constexpr int kGroup   = kHeadsQ / kHeadsKV;
constexpr int kRowsHead = 32;
constexpr int kBlockN   = 128;
constexpr int kThreads  = 256;
constexpr int kStages   = 3;
constexpr int kQRowStride  = kHeadsQ * kDim;
constexpr int kKVRowStride = kHeadsKV * kDim;
constexpr unsigned kFull = 0xffffffffu;

constexpr float kScale    = 0.08838834764831845f;
constexpr float kLog2e    = 1.4426950408889634f;
constexpr float kScaleL2e = kScale * kLog2e;

DEV void cp_async16(void* dst, const void* src) {
    uint32_t d = (uint32_t)__cvta_generic_to_shared(dst);
    asm volatile(\"cp.async.cg.shared.global [%0], [%1], 16;\\n\" ::\"r\"(d), \"l\"(src));
}
DEV void cp_commit() { asm volatile(\"cp.async.commit_group;\\n\"); }
template <int kN> DEV void cp_wait() { asm volatile(\"cp.async.wait_group %0;\\n\" ::\"n\"(kN)); }
DEV float ex2(float x) { float y; asm(\"ex2.approx.f32 %0, %1;\\n\" : \"=f\"(y) : \"f\"(x)); return y; }
DEV uint32_t pack_bf16(float lo, float hi) {
    __nv_bfloat162 h = __floats2bfloat162_rn(lo, hi);
    return *reinterpret_cast<uint32_t*>(&h);
}

// ------------------------------------------------------- core matrix layout ---
constexpr int kCoreDimB = 144;
constexpr int kCoreKvB  = (kDim / 8) * kCoreDimB;
constexpr int kTileB    = (kBlockN / 8) * kCoreKvB;
constexpr int kStageB   = 2 * kTileB;
constexpr int kSmemB    = kStages * kStageB;
constexpr int kDRegs    = kBlockN / 2;

DEV uint64_t core_desc(const void* p, int lbo_b, int sbo_b) {
    const uint64_t a = (uint64_t)(uint32_t)__cvta_generic_to_shared(p);
    return ((a >> 4) & 0x3FFFULL) | ((uint64_t)(lbo_b >> 4) << 16) |
           ((uint64_t)(sbo_b >> 4) << 32);
}

DEV void load_tile_b(const __nv_bfloat16* __restrict__ src, char* dst, int tid) {
    const char* g = reinterpret_cast<const char*>(src);
#pragma unroll
    for (int i = 0; i < 8; ++i) {
        const int c  = tid + i * kThreads;
        const int kv = c >> 4;
        const int j  = c & 15;
        cp_async16(dst + (kv & 7) * 16 + (kv >> 3) * kCoreKvB + j * kCoreDimB,
                   g + (size_t)kv * (kKVRowStride * 2) + j * 16);
    }
}

DEV void wgmma_m64n128k16(float (&d)[64], const uint32_t (&a)[4], uint64_t bd) {
    asm volatile(
        \"wgmma.mma_async.sync.aligned.m64n128k16.f32.bf16.bf16 {%D64}, \"
        \"{%64,%65,%66,%67}, %68, 1, 1, 1, 0;\\n\"
        : D_OPS
        : \"r\"(a[0]), \"r\"(a[1]), \"r\"(a[2]), \"r\"(a[3]), \"l\"(bd));
}

// ------------------------------------------------------------------ kernel ---
__global__ void __launch_bounds__(kThreads, 1)
gqa_wgmma(const __nv_bfloat16* __restrict__ q, const __nv_bfloat16* __restrict__ k,
          const __nv_bfloat16* __restrict__ v, __nv_bfloat16* __restrict__ o,
          int seq, int qblocks) {
#if defined(__CUDA_ARCH_FEAT_SM90_ALL)
    extern __shared__ __nv_bfloat16 smem[];
    char* st = reinterpret_cast<char*>(smem);
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int wg = (tid >> 7) & 1;
    const int w  = (tid >> 5) & 3;

    const int grp = blockIdx.x / qblocks;
    const int qb  = qblocks - 1 - (blockIdx.x % qblocks);
    const int q0  = qb * kRowsHead;
    const int kvl = (q0 + kRowsHead - 1) >> 7;

    const int r0 = 16 * w + (lane >> 2);
    const int r1 = r0 + 8;
    const int hq0 = grp * kGroup + 2 * wg + (r0 >> 5);
    const int hq1 = grp * kGroup + 2 * wg + (r1 >> 5);
    const int rr0 = r0 & 31;
    const int rr1 = r1 & 31;
    const int c2 = (lane & 3) * 2;

    const __nv_bfloat16* q0p = q + ((size_t)(q0 + rr0) * kHeadsQ + hq0) * kDim;
    const __nv_bfloat16* q1p = q + ((size_t)(q0 + rr1) * kHeadsQ + hq1) * kDim;
    uint32_t aq[8][4];
#pragma unroll
    for (int i = 0; i < 8; ++i) {
        aq[i][0] = *reinterpret_cast<const uint32_t*>(q0p + 16 * i + c2);
        aq[i][1] = *reinterpret_cast<const uint32_t*>(q1p + 16 * i + c2);
        aq[i][2] = *reinterpret_cast<const uint32_t*>(q0p + 16 * i + 8 + c2);
        aq[i][3] = *reinterpret_cast<const uint32_t*>(q1p + 16 * i + 8 + c2);
    }

    float acc[kDRegs];
#pragma unroll
    for (int i = 0; i < kDRegs; ++i) acc[i] = 0.f;
    float mstat[2] = {-INFINITY, -INFINITY};
    float lstat[2] = {0.f, 0.f};

    const __nv_bfloat16* kg = k + grp * kDim;
    const __nv_bfloat16* vg = v + grp * kDim;

#pragma unroll
    for (int s = 0; s < kStages - 1; ++s) {
        if (s <= kvl) {
            load_tile_b(kg + (size_t)s * kBlockN * kKVRowStride, st + s * kStageB, tid);
            load_tile_b(vg + (size_t)s * kBlockN * kKVRowStride, st + s * kStageB + kTileB, tid);
            cp_commit();
        }
    }
    asm volatile(\"wgmma.fence.sync.aligned;\\n\" ::);

    for (int j = 0; j <= kvl; ++j) {
        cp_wait<kStages - 2>();
        __syncthreads();
        asm volatile(\"fence.proxy.async.shared::cta;\\n\" ::);

        const int s = j % kStages;
        char* kt = st + s * kStageB;
        uint64_t kd = core_desc(kt, kCoreDimB, kCoreKvB);
        uint64_t vd = core_desc(kt + kTileB, kCoreKvB, kCoreDimB);

        float sc[kDRegs];
#pragma unroll
        for (int i = 0; i < kDRegs; ++i) sc[i] = 0.f;
#pragma unroll
        for (int i = 0; i < 8; ++i) wgmma_m64n128k16(sc, aq[i], kd + 18 * i);
        asm volatile(\"wgmma.commit_group.sync.aligned;\\n\" ::);
        asm volatile(\"wgmma.wait_group.sync.aligned 0;\\n\" ::);

        // ---- prefetch tile j + kStages - 1 (its buffer is now free) ----
        const int pf = j + kStages - 1;
        if (pf <= kvl) {
            char* pd = st + (pf % kStages) * kStageB;
            load_tile_b(kg + (size_t)pf * kBlockN * kKVRowStride, pd, tid);
            load_tile_b(vg + (size_t)pf * kBlockN * kKVRowStride, pd + kTileB, tid);
            cp_commit();
        }

        // ---- causal mask on the tile that straddles the diagonal ----
        if (j == kvl) {
            const int lim0 = q0 + rr0;
            const int lim1 = q0 + rr1;
            const int base = j * kBlockN + c2;
#pragma unroll
            for (int g = 0; g < 16; ++g) {
                const int c = base + 8 * g;
                sc[4 * g + 0] = (c <= lim0) ? sc[4 * g + 0] : -INFINITY;
                sc[4 * g + 1] = (c + 1 <= lim0) ? sc[4 * g + 1] : -INFINITY;
                sc[4 * g + 2] = (c <= lim1) ? sc[4 * g + 2] : -INFINITY;
                sc[4 * g + 3] = (c + 1 <= lim1) ? sc[4 * g + 3] : -INFINITY;
            }
        }

        // ---- row statistics ----
        float mx0 = -INFINITY, mx1 = -INFINITY;
#pragma unroll
        for (int g = 0; g < 16; ++g) {
            mx0 = fmaxf(mx0, fmaxf(sc[4 * g + 0], sc[4 * g + 1]));
            mx1 = fmaxf(mx1, fmaxf(sc[4 * g + 2], sc[4 * g + 3]));
        }
        mx0 = fmaxf(mx0, __shfl_xor_sync(kFull, mx0, 1));
        mx0 = fmaxf(mx0, __shfl_xor_sync(kFull, mx0, 2));
        mx1 = fmaxf(mx1, __shfl_xor_sync(kFull, mx1, 1));
        mx1 = fmaxf(mx1, __shfl_xor_sync(kFull, mx1, 2));
        const float nm0 = fmaxf(mstat[0], mx0 * kScaleL2e);
        const float nm1 = fmaxf(mstat[1], mx1 * kScaleL2e);
        const float alpha0 = ex2(mstat[0] - nm0);
        const float alpha1 = ex2(mstat[1] - nm1);
        mstat[0] = nm0;
        mstat[1] = nm1;

        float sum0 = 0.f, sum1 = 0.f;
#pragma unroll
        for (int g = 0; g < 16; ++g) {
            const float p0 = ex2(fmaf(sc[4 * g + 0], kScaleL2e, -nm0));
            const float p1 = ex2(fmaf(sc[4 * g + 1], kScaleL2e, -nm0));
            const float p2 = ex2(fmaf(sc[4 * g + 2], kScaleL2e, -nm1));
            const float p3 = ex2(fmaf(sc[4 * g + 3], kScaleL2e, -nm1));
            sc[4 * g + 0] = p0; sc[4 * g + 1] = p1;
            sc[4 * g + 2] = p2; sc[4 * g + 3] = p3;
            sum0 += p0 + p1;
            sum1 += p2 + p3;
        }
        sum0 += __shfl_xor_sync(kFull, sum0, 1);
        sum0 += __shfl_xor_sync(kFull, sum0, 2);
        sum1 += __shfl_xor_sync(kFull, sum1, 1);
        sum1 += __shfl_xor_sync(kFull, sum1, 2);
        lstat[0] = lstat[0] * alpha0 + sum0;
        lstat[1] = lstat[1] * alpha1 + sum1;

        if (alpha0 "'!= 1.f) {
#pragma unroll
            for (int g = 0; g < 16; ++g) { acc[4*g+0] *= alpha0; acc[4*g+1] *= alpha0; }
        }
        if (alpha1 != 1.f) {
#pragma unroll
            for (int g = 0; g < 16; ++g) { acc[4*g+2] *= alpha1; acc[4*g+3] *= alpha1; }
        }

        // ---- O += P V ----
        asm volatile("wgmma.fence.sync.aligned;'"\\n\" ::);
#pragma unroll
        for (int i = 0; i < 8; ++i) {
            const uint32_t pf[4] = {pack_bf16(sc[8*i+0], sc[8*i+1]),
                                    pack_bf16(sc[8*i+2], sc[8*i+3]),
                                    pack_bf16(sc[8*i+4], sc[8*i+5]),
                                    pack_bf16(sc[8*i+6], sc[8*i+7])};
            wgmma_m64n128k16(acc, pf, vd + 288 * i);
        }
        asm volatile(\"wgmma.commit_group.sync.aligned;\\n\" ::);
    }
    asm volatile(\"wgmma.wait_group.sync.aligned 0;\\n\" ::);

    // ---- normalise and store ----
    const float inv0 = 1.f / lstat[0];
    const float inv1 = 1.f / lstat[1];
    __nv_bfloat16* o0p = o + ((size_t)(q0 + rr0) * kHeadsQ + hq0) * kDim;
    __nv_bfloat16* o1p = o + ((size_t)(q0 + rr1) * kHeadsQ + hq1) * kDim;
#pragma unroll
    for (int g = 0; g < 16; ++g) {
        const __nv_bfloat162 lo = __floats2bfloat162_rn(acc[4*g+0] * inv0, acc[4*g+1] * inv0);
        const __nv_bfloat162 hi = __floats2bfloat162_rn(acc[4*g+2] * inv1, acc[4*g+3] * inv1);
        *reinterpret_cast<__nv_bfloat162*>(o0p + 8 * g + c2) = lo;
        *reinterpret_cast<__nv_bfloat162*>(o1p + 8 * g + c2) = hi;
    }
#endif
}
'''.replace(\"{%D64}\", \"{\" + d_list + \"}\").replace(\"D_OPS\", d_ops)

driver = r'''
// ------------------------------------------------------------------ driver ---
static __nv_bfloat16 h2bf(float x) { return __float2bfloat16(x); }

int main(int argc, char** argv) {
  const int seq = argc > 1 ? atoi(argv[1]) : 256;
  const size_t nq = (size_t)seq * kHeadsQ * kDim;
  const size_t nk = (size_t)seq * kHeadsKV * kDim;
  __nv_bfloat16 *hq, *hk, *hv, *ho, *ref;
  cudaMallocHost(&hq, nq * 2); cudaMallocHost(&hk, nk * 2);
  cudaMallocHost(&hv, nk * 2); cudaMallocHost(&ho, nq * 2);
  cudaMallocHost(&ref, nq * 2);
  srand(1234);
  for (size_t i = 0; i < nq; ++i) hq[i] = h2bf((float)(rand() % 2000 - 1000) / 1000.f);
  for (size_t i = 0; i < nk; ++i) {
    hk[i] = h2bf((float)(rand() % 2000 - 1000) / 1000.f);
    hv[i] = h2bf((float)(rand() % 2000 - 1000) / 1000.f);
  }
  // CPU reference (fp32)
  const float scale = 1.0f / sqrtf((float)kDim);
  for (int s = 0; s < seq; ++s)
    for (int h = 0; h < kHeadsQ; ++h) {
      const int kvh = h / kGroup;
      float* sc = (float*)malloc((s + 1) * sizeof(float));
      float mx = -1e30f;
      for (int t = 0; t <= s; ++t) {
        float d = 0.f;
        for (int c = 0; c < kDim; ++c)
          d += (float)hq[((size_t)s * kHeadsQ + h) * kDim + c] * (float)hk[((size_t)t * kHeadsKV + kvh) * kDim + c];
        sc[t] = d * scale;
        if (sc[t] > mx) mx = sc[t];
      }
      float sum = 0.f;
      for (int t = 0; t <= s; ++t) { sc[t] = expf(sc[t] - mx); sum += sc[t]; }
      for (int c = 0; c < kDim; ++c) {
        float acc = 0.f;
        for (int t = 0; t <= s; ++t)
          acc += sc[t] * (float)hv[((size_t)t * kHeadsKV + kvh) * kDim + c];
        ref[((size_t)s * kHeadsQ + h) * kDim + c] = h2bf(acc / sum);
      }
      free(sc);
    }
  __nv_bfloat16 *dq, *dk, *dv, *do_;
  cudaMalloc(&dq, nq * 2); cudaMalloc(&dk, nk * 2);
  cudaMalloc(&dv, nk * 2); cudaMalloc(&do_, nq * 2);
  cudaMemcpy(dq, hq, nq * 2, cudaMemcpyHostToDevice);
  cudaMemcpy(dk, hk, nk * 2, cudaMemcpyHostToDevice);
  cudaMemcpy(dv, hv, nk * 2, cudaMemcpyHostToDevice);
  cudaMemset(do_, 0, nq * 2);
  cudaFuncSetAttribute(gqa_wgmma, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemB);
  const int qblocks = seq / kRowsHead;
  gqa_wgmma<<<qblocks * kHeadsKV, kThreads, kSmemB>>>(dq, dk, dv, do_, seq, qblocks);
  cudaError_t e = cudaDeviceSynchronize();
  if (e) { printf(\"CUDA error: %s\\n\", cudaGetErrorString(e)); return 1; }
  cudaMemcpy(ho, do_, nq * 2, cudaMemcpyDeviceToHost);
  double maxabs = 0, maxrel = 0; long bad = 0;
  for (size_t i = 0; i < nq; ++i) {
    double a = (double)ho[i], b = (double)ref[i];
    double d = fabs(a - b);
    if (d > maxabs) maxabs = d;
    if (fabs(b) > 1e-3 && d / fabs(b) > maxrel) maxrel = d / fabs(b);
    if (d > 0.02) ++bad;
  }
  printf(\"seq=%d maxabs=%g maxrel=%g bad=%ld / %zu\\n\", seq, maxabs, maxrel, bad, nq);
  FILE* f = fopen(\"/tmp/wgtest/o.bin\", \"wb\");
  fwrite(ho, 2, nq, f); fclose(f);
  FILE* g = fopen(\"/tmp/wgtest/r.bin\", \"wb\");
  fwrite(ref, 2, nq, g); fclose(g);
  return bad ? 1 : 0;
}
