driver = r'''
// ------------------------------------------------------------------ driver ---
static __nv_bfloat16 h2bf(float x) { return __float2bfloat16(x); }

int main(int argc, char** argv) {
  const int seq = argc > 1 ? atoi(argv[1]) : 256;
  const size_t nq = (size_t)seq * kHeadsQ * kDim;
  const size_t nk = (size_t)seq * kHeadsKV * kDim;
  __nv_bfloat16 *hq, *hk, *hv, *ho, *ref;
  cudaMallocHost(&hq, nq * 2); cudaMallocHost(&hk, nk * 2);
  cudaMallocHost(&hv, nk * 2); cudaMallocHost(&ho, nq * 2);
  cudaMallocHost(&ref, nq * 2);
  srand(1234);
  for (size_t i = 0; i < nq; ++i) hq[i] = h2bf((float)(rand() % 2000 - 1000) / 1000.f);
  for (size_t i = 0; i < nk; ++i) {
    hk[i] = h2bf((float)(rand() % 2000 - 1000) / 1000.f);
    hv[i] = h2bf((float)(rand() % 2000 - 1000) / 1000.f);
  }
  // CPU reference (fp32)
  const float scale = 1.0f / sqrtf((float)kDim);
  for (int s = 0; s < seq; ++s)
    for (int h = 0; h < kHeadsQ; ++h) {
      const int kvh = h / kGroup;
      float* sc = (float*)malloc((s + 1) * sizeof(float));
      float mx = -1e30f;
      for (int t = 0; t <= s; ++t) {
        float d = 0.f;
        for (int c = 0; c < kDim; ++c)
          d += (float)hq[((size_t)s * kHeadsQ + h) * kDim + c] * (float)hk[((size_t)t * kHeadsKV + kvh) * kDim + c];
        sc[t] = d * scale;
        if (sc[t] > mx) mx = sc[t];
      }
      float sum = 0.f;
      for (int t = 0; t <= s; ++t) { sc[t] = expf(sc[t] - mx); sum += sc[t]; }
      for (int c = 0; c < kDim; ++c) {
        float acc = 0.f;
        for (int t = 0; t <= s; ++t)
          acc += sc[t] * (float)hv[((size_t)t * kHeadsKV + kvh) * kDim + c];
        ref[((size_t)s * kHeadsQ + h) * kDim + c] = h2bf(acc / sum);
      }
      free(sc);
    }
  __nv_bfloat16 *dq, *dk, *dv, *do_;
  cudaMalloc(&dq, nq * 2); cudaMalloc(&dk, nk * 2);
  cudaMalloc(&dv, nk * 2); cudaMalloc(&do_, nq * 2);
  cudaMemcpy(dq, hq, nq * 2, cudaMemcpyHostToDevice);
  cudaMemcpy(dk, hk, nk * 2, cudaMemcpyHostToDevice);
  cudaMemcpy(dv, hv, nk * 2, cudaMemcpyHostToDevice);
  cudaMemset(do_, 0, nq * 2);
  cudaFuncSetAttribute(gqa_wgmma, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemB);
  const int qblocks = seq / kRowsHead;
  gqa_wgmma<<<qblocks * kHeadsKV, kThreads, kSmemB>>>(dq, dk, dv, do_, seq, qblocks);
  cudaError_t e = cudaDeviceSynchronize();
  if (e) { printf(\"CUDA error: %s\\n\", cudaGetErrorString(e)); return 1; }
  cudaMemcpy(ho, do_, nq * 2, cudaMemcpyDeviceToHost);
  double maxabs = 0, maxrel = 0; long bad = 0;
  for (size_t i = 0; i < nq; ++i) {
    double a = (double)ho[i], b = (double)ref[i];
    double d = fabs(a - b);
    if (d > maxabs) maxabs = d;
    if (fabs(b) > 1e-3 && d / fabs(b) > maxrel) maxrel = d / fabs(b);
    if (d > 0.02) ++bad;
  }
  printf(\"seq=%d maxabs=%g maxrel=%g bad=%ld / %zu\\n\", seq, maxabs, maxrel, bad, nq);
  FILE* f = fopen(\"/tmp/wgtest/o.bin\", \"wb\");
  fwrite(ho, 2, nq, f); fclose(f);
  FILE* g = fopen(\"/tmp/wgtest/r.bin\", \"wb\");
  fwrite(ref, 2, nq, g); fclose(g);
  return bad ? 1 : 0;
}
'''
