220	    // Rescaling is a no-op whenever the running maximum did not move, which is
221	    // the common case; skipping it saves 64 multiplies per tile.
222	    if (alpha0 != 1.f) {
223	#pragma unroll
224	        for (int nb = 0; nb < kNB; ++nb) {
225	            acc[nb][0] *= alpha0;
226	            acc[nb][1] *= alpha0;
227	        }
228	    }
229	    if (alpha1 != 1.f) {
230	#pragma unroll
231	        for (int nb = 0; nb < kNB; ++nb) {
232	            acc[nb][2] *= alpha1;
233	            acc[nb][3] *= alpha1;
234	        }
235	    }
236	
237	    // ---- weights and row sums ----
238	    float rsum0[kNB / 2], rsum1[kNB / 2];
239	#pragma unroll
240	    for (int i = 0; i < kNB / 2; ++i) {
241	        const float p0 = ex2(fmaf(s[2 * i][0], kScaleL2e, -nm0));
242	        const float p1 = ex2(fmaf(s[2 * i][1], kScaleL2e, -nm0));
243	        const float p2 = ex2(fmaf(s[2 * i][2], kScaleL2e, -nm1));
244	        const float p3 = ex2(fmaf(s[2 * i][3], kScaleL2e, -nm1));
245	        const float q0 = ex2(fmaf(s[2 * i + 1][0], kScaleL2e, -nm0));
