 27	DEV void cp_async16(void* dst, const void* src) {
 28	    uint32_t d = (uint32_t)__cvta_generic_to_shared(dst);
 29	    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" ::"r"(d), "l"(src));
 30	}
 31	DEV void cp_commit() { asm volatile("cp.async.commit_group;\n"); }
 32	template <int kN> DEV void cp_wait() { asm volatile("cp.async.wait_group %0;\n" ::"n"(kN)); }
 33	DEV float ex2(float x) { float y; asm("ex2.approx.f32 %0, %1;\n" : "=f"(y) : "f"(x)); return y; }
 34	DEV uint32_t pack_bf16(float lo, float hi) {
 35	    __nv_bfloat162 h = __floats2bfloat162_rn(lo, hi);
 36	    return *reinterpret_cast<uint32_t*>(&h);
 37	}
