 47	DEV uint64_t core_desc(const void* p, int lbo_b, int sbo_b) {
 48	    const uint64_t a = (uint64_t)(uint32_t)__cvta_generic_to_shared(p);
 49	    return ((a >> 4) & 0x3FFFULL) | ((uint64_t)(lbo_b >> 4) << 16) |
 50	           ((uint64_t)(sbo_b >> 4) << 32);
 51	}
