 53	DEV void load_tile_b(const __nv_bfloat16* __restrict__ src, char* dst, int tid) {
 54	    const char* g = reinterpret_cast<const char*>(src);
 55	#pragma unroll
 56	    for (int i = 0; i < 8; ++i) {
 57	        const int c  = tid + i * kThreads;
 58	        const int kv = c >> 4;
 59	        const int j  = c & 15;
 60	        cp_async16(dst + (kv & 7) * 16 + (kv >> 3) * kCoreKvB + j * kCoreDimB,
 61	                   g + (size_t)kv * (kKVRowStride * 2) + j * 16);
 62	    }
 63	}
