137	__global__ void __launch_bounds__(kThreads, 1)
138	gqa_wgmma(const __nv_bfloat16* __restrict__ q, const __nv_bfloat16* __restrict__ k,
139	          const __nv_bfloat16* __restrict__ v, __nv_bfloat16* __restrict__ o,
140	          int seq, int qblocks) {
141	#if defined(__CUDA_ARCH_FEAT_SM90_ALL)
142	    extern __shared__ __nv_bfloat16 smem[];
143	    char* st = reinterpret_cast<char*>(smem);
144	    const int tid = threadIdx.x;
145	    const int lane = tid & 31;
146	    const int wg = (tid >> 7) & 1;
147	    const int w  = (tid >> 5) & 3;
148	
149	    const int grp = blockIdx.x / qblocks;
150	    const int qb  = qblocks - 1 - (blockIdx.x % qblocks);
151	    const int q0  = qb * kRowsHead;
152	    const int kvl = (q0 + kRowsHead - 1) >> 7;
153	
154	    const int r0 = 16 * w + (lane >> 2);
155	    const int r1 = r0 + 8;
156	    const int hq0 = grp * kGroup + 2 * wg + (r0 >> 5);
157	    const int hq1 = grp * kGroup + 2 * wg + (r1 >> 5);
158	    const int rr0 = r0 & 31;
159	    const int rr1 = r1 & 31;
160	    const int c2 = (lane & 3) * 2;
161	
162	    const __nv_bfloat16* q0p = q + ((size_t)(q0 + rr0) * kHeadsQ + hq0) * kDim;
163	    const __nv_bfloat16* q1p = q + ((size_t)(q0 + rr1) * kHeadsQ + hq1) * kDim;
164	    uint32_t aq[8][4];
165	#pragma unroll
166	    for (int i = 0; i < 8; ++i) {
167	        aq[i][0] = *reinterpret_cast<const uint32_t*>(q0p + 16 * i + c2);
168	        aq[i][1] = *reinterpret_cast<const uint32_t*>(q1p + 16 * i + c2);
169	        aq[i][2] = *reinterpret_cast<const uint32_t*>(q0p + 16 * i + 8 + c2);
170	        aq[i][3] = *reinterpret_cast<const uint32_t*>(q1p + 16 * i + 8 + c2);
171	    }
172	
173	    float acc[kDRegs];
174	#pragma unroll
175	    for (int i = 0; i < kDRegs; ++i) acc[i] = 0.f;
176	    float mstat[2] = {-INFINITY, -INFINITY};
177	    float lstat[2] = {0.f, 0.f};
178	
179	    const __nv_bfloat16* kg = k + grp * kDim;
180	    const __nv_bfloat16* vg = v + grp * kDim;
181	
182	#pragma unroll
183	    for (int s = 0; s < kStages - 1; ++s) {
184	        if (s <= kvl) {
185	            load_tile_b(kg + (size_t)s * kBlockN * kKVRowStride, st + s * kStageB, tid);
186	            load_tile_b(vg + (size_t)s * kBlockN * kKVRowStride, st + s * kStageB + kTileB, tid);
187	            cp_commit();
188	        }
189	    }
190	    asm volatile("wgmma.fence.sync.aligned;\n" ::);
191	
192	    for (int j = 0; j <= kvl; ++j) {
193	        cp_wait<kStages - 2>();
194	        __syncthreads();
195	        asm volatile("fence.proxy.async.shared::cta;\n" ::);
196	
197	        const int s = j % kStages;
198	        char* kt = st + s * kStageB;
199	        uint64_t kd = core_desc(kt, kCoreDimB, kCoreKvB);
200	        uint64_t vd = core_desc(kt + kTileB, kCoreKvB, kCoreDimB);
201	
202	        float sc[kDRegs];
203	#pragma unroll
204	        for (int i = 0; i < kDRegs; ++i) sc[i] = 0.f;
205	#pragma unroll
206	        for (int i = 0; i < 8; ++i) wgmma_m64n128k16(sc, aq[i], kd + 18 * i);
207	        asm volatile("wgmma.commit_group.sync.aligned;\n" ::);
208	        asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::);
209	
210	        // ---- prefetch tile j + kStages - 1 (its buffer is now free) ----
211	        const int pf = j + kStages - 1;
212	        if (pf <= kvl) {
213	            char* pd = st + (pf % kStages) * kStageB;
214	            load_tile_b(kg + (size_t)pf * kBlockN * kKVRowStride, pd, tid);
215	            load_tile_b(vg + (size_t)pf * kBlockN * kKVRowStride, pd + kTileB, tid);
216	            cp_commit();
217	        }
218	
219	        // ---- causal mask on the tile that straddles the diagonal ----
220	        if (j == kvl) {
221	            const int lim0 = q0 + rr0;
222	            const int lim1 = q0 + rr1;
223	            const int base = j * kBlockN + c2;
224	#pragma unroll
225	            for (int g = 0; g < 16; ++g) {
226	                const int c = base + 8 * g;
227	                sc[4 * g + 0] = (c <= lim0) ? sc[4 * g + 0] : -INFINITY;
228	                sc[4 * g + 1] = (c + 1 <= lim0) ? sc[4 * g + 1] : -INFINITY;
229	                sc[4 * g + 2] = (c <= lim1) ? sc[4 * g + 2] : -INFINITY;
230	                sc[4 * g + 3] = (c + 1 <= lim1) ? sc[4 * g + 3] : -INFINITY;
231	            }
232	        }
233	
234	        // ---- row statistics ----
235	        float mx0 = -INFINITY, mx1 = -INFINITY;
236	#pragma unroll
237	        for (int g = 0; g < 16; ++g) {
238	            mx0 = fmaxf(mx0, fmaxf(sc[4 * g + 0], sc[4 * g + 1]));
239	            mx1 = fmaxf(mx1, fmaxf(sc[4 * g + 2], sc[4 * g + 3]));
240	        }
241	        mx0 = fmaxf(mx0, __shfl_xor_sync(kFull, mx0, 1));
242	        mx0 = fmaxf(mx0, __shfl_xor_sync(kFull, mx0, 2));
243	        mx1 = fmaxf(mx1, __shfl_xor_sync(kFull, mx1, 1));
244	        mx1 = fmaxf(mx1, __shfl_xor_sync(kFull, mx1, 2));
245	        const float nm0 = fmaxf(mstat[0], mx0 * kScaleL2e);
246	        const float nm1 = fmaxf(mstat[1], mx1 * kScaleL2e);
247	        const float alpha0 = ex2(mstat[0] - nm0);
248	        const float alpha1 = ex2(mstat[1] - nm1);
249	        mstat[0] = nm0;
250	        mstat[1] = nm1;
251	
252	        float sum0 = 0.f, sum1 = 0.f;
253	#pragma unroll
254	        for (int g = 0; g < 16; ++g) {
255	            const float p0 = ex2(fmaf(sc[4 * g + 0], kScaleL2e, -nm0));
256	            const float p1 = ex2(fmaf(sc[4 * g + 1], kScaleL2e, -nm0));
257	            const float p2 = ex2(fmaf(sc[4 * g + 2], kScaleL2e, -nm1));
258	            const float p3 = ex2(fmaf(sc[4 * g + 3], kScaleL2e, -nm1));
259	            sc[4 * g + 0] = p0; sc[4 * g + 1] = p1;
260	            sc[4 * g + 2] = p2; sc[4 * g + 3] = p3;
261	            sum0 += p0 + p1;
262	            sum1 += p2 + p3;
263	        }
264	        sum0 += __shfl_xor_sync(kFull, sum0, 1);
265	        sum0 += __shfl_xor_sync(kFull, sum0, 2);
266	        sum1 += __shfl_xor_sync(kFull, sum1, 1);
267	        sum1 += __shfl_xor_sync(kFull, sum1, 2);
268	        lstat[0] = lstat[0] * alpha0 + sum0;
269	        lstat[1] = lstat[1] * alpha1 + sum1;
270	
271	        if (alpha0 != 1.f) {
272	#pragma unroll
273	            for (int g = 0; g < 16; ++g) { acc[4*g+0] *= alpha0; acc[4*g+1] *= alpha0; }
274	        }
275	        if (alpha1 != 1.f) {
276	#pragma unroll
277	            for (int g = 0; g < 16; ++g) { acc[4*g+2] *= alpha1; acc[4*g+3] *= alpha1; }
278	        }
279	
280	        // ---- O += P V ----
281	        asm volatile("wgmma.fence.sync.aligned;\n" ::);
282	#pragma unroll
283	        for (int i = 0; i < 8; ++i) {
284	            const uint32_t pf[4] = {pack_bf16(sc[8*i+0], sc[8*i+1]),
285	                                    pack_bf16(sc[8*i+2], sc[8*i+3]),
286	                                    pack_bf16(sc[8*i+4], sc[8*i+5]),
287	                                    pack_bf16(sc[8*i+6], sc[8*i+7])};
288	            wgmma_m64n128k16(acc, pf, vd + 288 * i);
289	        }
290	        asm volatile("wgmma.commit_group.sync.aligned;\n" ::);
291	    }
292	    asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::);
293	
294	    // ---- normalise and store ----
295	    const float inv0 = 1.f / lstat[0];
296	    const float inv1 = 1.f / lstat[1];
297	    __nv_bfloat16* o0p = o + ((size_t)(q0 + rr0) * kHeadsQ + hq0) * kDim;
298	    __nv_bfloat16* o1p = o + ((size_t)(q0 + rr1) * kHeadsQ + hq1) * kDim;
299	#pragma unroll
300	    for (int g = 0; g < 16; ++g) {
301	        const __nv_bfloat162 lo = __floats2bfloat162_rn(acc[4*g+0] * inv0, acc[4*g+1] * inv0);
302	        const __nv_bfloat162 hi = __floats2bfloat162_rn(acc[4*g+2] * inv1, acc[4*g+3] * inv1);
303	        *reinterpret_cast<__nv_bfloat162*>(o0p + 8 * g + c2) = lo;
304	        *reinterpret_cast<__nv_bfloat162*>(o1p + 8 * g + c2) = hi;
305	    }
306	#endif
307	}
