312	int main(int argc, char** argv) {
313	  const int seq = argc > 1 ? atoi(argv[1]) : 256;
314	  const size_t nq = (size_t)seq * kHeadsQ * kDim;
315	  const size_t nk = (size_t)seq * kHeadsKV * kDim;
316	  __nv_bfloat16 *hq, *hk, *hv, *ho, *ref;
317	  cudaMallocHost(&hq, nq * 2); cudaMallocHost(&hk, nk * 2);
318	  cudaMallocHost(&hv, nk * 2); cudaMallocHost(&ho, nq * 2);
319	  cudaMallocHost(&ref, nq * 2);
320	  srand(1234);
321	  for (size_t i = 0; i < nq; ++i) hq[i] = h2bf((float)(rand() % 2000 - 1000) / 1000.f);
322	  for (size_t i = 0; i < nk; ++i) {
323	    hk[i] = h2bf((float)(rand() % 2000 - 1000) / 1000.f);
324	    hv[i] = h2bf((float)(rand() % 2000 - 1000) / 1000.f);
325	  }
326	  // CPU reference (fp32)
327	  const float scale = 1.0f / sqrtf((float)kDim);
328	  for (int s = 0; s < seq; ++s)
329	    for (int h = 0; h < kHeadsQ; ++h) {
330	      const int kvh = h / kGroup;
331	      float* sc = (float*)malloc((s + 1) * sizeof(float));
332	      float mx = -1e30f;
333	      for (int t = 0; t <= s; ++t) {
334	        float d = 0.f;
335	        for (int c = 0; c < kDim; ++c)
336	          d += (float)hq[((size_t)s * kHeadsQ + h) * kDim + c] * (float)hk[((size_t)t * kHeadsKV + kvh) * kDim + c];
337	        sc[t] = d * scale;
338	        if (sc[t] > mx) mx = sc[t];
339	      }
340	      float sum = 0.f;
341	      for (int t = 0; t <= s; ++t) { sc[t] = expf(sc[t] - mx); sum += sc[t]; }
342	      for (int c = 0; c < kDim; ++c) {
343	        float acc = 0.f;
344	        for (int t = 0; t <= s; ++t)
345	          acc += sc[t] * (float)hv[((size_t)t * kHeadsKV + kvh) * kDim + c];
346	        ref[((size_t)s * kHeadsQ + h) * kDim + c] = h2bf(acc / sum);
347	      }
348	      free(sc);
349	    }
350	  __nv_bfloat16 *dq, *dk, *dv, *do_;
351	  cudaMalloc(&dq, nq * 2); cudaMalloc(&dk, nk * 2);
352	  cudaMalloc(&dv, nk * 2); cudaMalloc(&do_, nq * 2);
353	  cudaMemcpy(dq, hq, nq * 2, cudaMemcpyHostToDevice);
354	  cudaMemcpy(dk, hk, nk * 2, cudaMemcpyHostToDevice);
355	  cudaMemcpy(dv, hv, nk * 2, cudaMemcpyHostToDevice);
356	  cudaMemset(do_, 0, nq * 2);
357	  cudaFuncSetAttribute(gqa_wgmma, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemB);
358	  const int qblocks = seq / kRowsHead;
359	  gqa_wgmma<<<qblocks * kHeadsKV, kThreads, kSmemB>>>(dq, dk, dv, do_, seq, qblocks);
360	  cudaError_t e = cudaDeviceSynchronize();
361	  if (e) { printf("CUDA error: %s\n", cudaGetErrorString(e)); return 1; }
362	  cudaMemcpy(ho, do_, nq * 2, cudaMemcpyDeviceToHost);
363	  double maxabs = 0, maxrel = 0; long bad = 0;
364	  for (size_t i = 0; i < nq; ++i) {
365	    double a = (double)ho[i], b = (double)ref[i];
366	    double d = fabs(a - b);
367	    if (d > maxabs) maxabs = d;
368	    if (fabs(b) > 1e-3 && d / fabs(b) > maxrel) maxrel = d / fabs(b);
369	    if (d > 0.02) ++bad;
370	  }
371	  printf("seq=%d maxabs=%g maxrel=%g bad=%ld / %zu\n", seq, maxabs, maxrel, bad, nq);
372	  FILE* f = fopen("/tmp/wgtest/o.bin", "wb");
373	  fwrite(ho, 2, nq, f); fclose(f);
374	  FILE* g = fopen("/tmp/wgtest/r.bin", "wb");
375	  fwrite(ref, 2, nq, g); fclose(g);
376	  return bad ? 1 : 0;
377	}

