DEV void cp_commit(){asm volatile(\"cp.async.commit_group;\\n\");}
template<int kN> DEV void cp_wait(){asm volatile(\"cp.async.wait_group %0;\\n\" ::\"n\"(kN));}
DEV void load_tile(const __nv_bfloat16* __restrict__ src, char* dst, int tid){
  const char* g=reinterpret_cast<const char*>(src);
#pragma unroll
  for(int i=0;i<8;++i){int c=tid+i*kThreads;int kv=c>>4;int j=c&15;
    cp_async16(dst+(kv&7)*16+(kv>>3)*kSboB+j*kLboB, g+(size_t)kv*(kKVRowStride*2)+j*16);}
