__global__ void __launch_bounds__(kThreads,1) ldbw(const __nv_bfloat16* __restrict__ k,
    const __nv_bfloat16* __restrict__ v, int seq, int qblocks){
  extern __shared__ __nv_bfloat16 smem[];
  char* st=reinterpret_cast<char*>(smem);
  int tid=threadIdx.x;
  int grp=blockIdx.x/qblocks, qb=qblocks-1-(blockIdx.x%qblocks);
  int q0=qb*kRowsHead, kvl=(q0+kRowsHead-1)>>7;
  const __nv_bfloat16* kg=k+grp*kDim; const __nv_bfloat16* vg=v+grp*kDim;
#pragma unroll
  for(int s=0;s<kStages-1;++s) if(s<=kvl){
    load_tile(kg+(size_t)s*kBlockN*kKVRowStride, st+s*kStageB, tid);
    load_tile(vg+(size_t)s*kBlockN*kKVRowStride, st+s*kStageB+kTileB, tid);
    cp_commit();}
  for(int j=0;j<=kvl;++j){
    cp_wait<kStages-2>(); __syncthreads();
    int pf=j+kStages-1;
    if(pf<=kvl){char* pd=st+(pf%kStages)*kStageB;
      load_tile(kg+(size_t)pf*kBlockN*kKVRowStride, pd, tid);
      load_tile(vg+(size_t)pf*kBlockN*kKVRowStride, pd+kTileB, tid);
      cp_commit();}
  }
  cp_wait<0>();
}
int main(int argc,char**argv){
