  __nv_bfloat16 *hk,*hv; cudaMallocHost(&hk,nk*2); cudaMallocHost(&hv,nk*2);
  for(size_t i=0;i<nk;++i){hk[i]=__float2bfloat16(0.1f);hv[i]=__float2bfloat16(0.2f);}
  __nv_bfloat16 *dk,*dv; cudaMalloc(&dk,nk*2); cudaMalloc(&dv,nk*2);
  cudaMemcpy(dk,hk,nk*2,cudaMemcpyHostToDevice); cudaMemcpy(dv,hv,nk*2,cudaMemcpyHostToDevice);
  cudaFuncSetAttribute(ldbw,cudaFuncAttributeMaxDynamicSharedMemorySize,kSmemB);
  int qblocks=seq/kRowsHead, grid=qblocks*kHeadsKV;
  ldbw<<<grid,kThreads,kSmemB>>>(dk,dv,seq,qblocks);
  if(cudaDeviceSynchronize()){printf(\"err %s\\n\",cudaGetErrorString(cudaGetLastError()));return 1;}
  cudaEvent_t a,b; cudaEventCreate(&a); cudaEventCreate(&b);
  for(int i=0;i<2;++i) ldbw<<<grid,kThreads,kSmemB>>>(dk,dv,seq,qblocks);
  cudaEventRecord(a);
  for(int i=0;i<10;++i) ldbw<<<grid,kThreads,kSmemB>>>(dk,dv,seq,qblocks);
  cudaEventRecord(b); cudaEventSynchronize(b);
  float ms=0; cudaEventElapsedTime(&ms,a,b); ms/=10.f;
  // tiles
  long tiles=0; for(int qb=0;qb<qblocks;++qb){int q0=qb*kRowsHead;tiles+=((q0+kRowsHead-1)>>7)+1;}
  tiles*=kHeadsKV;
  double bytes=(double)tiles*kBlockN*kDim*2*2;
  printf(\"load-only seq=%d  %.4f ms  tiles=%ld  %.2f GB  %.2f TB/s\\n\",seq,ms,tiles,bytes/1e9,bytes/1e9/(ms/1e3)/1e3);
  return 0;
}
