#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cuda_runtime.h>
__device__ __forceinline__ void cpa(void* dst, const void* src){
  uint32_t d=(uint32_t)__cvta_generic_to_shared(dst);
  asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" ::"r"(d),"l"(src));}
template<int THREADS, int UNROLL, int DEPTH, int REPS>
__global__ void __launch_bounds__(THREADS) cpb(char* __restrict__ src, size_t nchunk){
  __shared__ __align__(1024) char buf[THREADS*16];
  size_t stride=(size_t)gridDim.x*THREADS;
  char* mine = buf + threadIdx.x*16;
  for(int r=0;r<REPS;++r){
    size_t i=(size_t)blockIdx.x*THREADS+threadIdx.x;
    for(; i<nchunk; i+=stride){
#pragma unroll
      for(int u=0;u<UNROLL;++u){ size_t j=i+(size_t)u*stride; if(j<nchunk) cpa(mine, src+j*16); }
      asm volatile("cp.async.commit_group;\n"::);
      asm volatile("cp.async.wait_group %0;\n" ::"n"(DEPTH));
    }
  }
  asm volatile("cp.async.wait_group 0;\n"::);
}
template<int THREADS,int UNROLL,int DEPTH,int REPS>
void run(char* src,size_t nchunk,int grid,const char* tag){
  cpb<THREADS,UNROLL,DEPTH,REPS><<<grid,THREADS>>>(src,nchunk);
  cudaDeviceSynchronize();
  cudaEvent_t a,b; cudaEventCreate(&a); cudaEventCreate(&b);
  cpb<THREADS,UNROLL,DEPTH,REPS><<<grid,THREADS>>>(src,nchunk); cudaEventRecord(a);
  for(int i=0;i<5;++i) cpb<THREADS,UNROLL,DEPTH,REPS><<<grid,THREADS>>>(src,nchunk);
  cudaEventRecord(b); cudaEventSynchronize(b);
  float ms; cudaEventElapsedTime(&ms,a,b); ms/=5;
  double bytes=(double)nchunk*16*REPS;
  printf("%-26s %.4f ms  %.2f TB/s\n",tag,ms,bytes/1e9/(ms/1e3)/1e3);
}
int main(){
