        asm volatile("wgmma.fence.sync.aligned;\n" ::);
#pragma unroll
        for (int i = 0; i < 8; ++i) {
            const uint32_t pf4[4] = {pack_bf16(sc[8 * i + 0], sc[8 * i + 1]),
