__device__ __forceinline__ void cpa_tile(const __nv_bfloat16* __restrict__ src, char* dst, int tid) {
    const int blk = tid >> 4, chunk = tid & 15;
    const char* gb = reinterpret_cast<const char*>(src) + (size_t)blk * (8 * kKVRowStride * 2) + chunk * 16;
    char* db = dst + blk * kSboB + chunk * kLboB;
#pragma unroll
    for (int r = 0; r < 8; ++r) cpa16(db + r * 16, gb + (size_t)r * (kKVRowStride * 2));
    asm volatile(\"cp.async.commit_group;\\n\" ::);
}

// kCopy: 0 = no copies, 1 = K only, 2 = K+V (mirrors the real kernel: 2 groups/stage)
template <int kCopy>
__global__ void __launch_bounds__(kThreads, 1) bench(const __nv_bfloat16* __restrict__ k,
                                                     const __nv_bfloat16* __restrict__ v,
                                                     int ntile, int niter, float* out) {
    extern __shared__ __nv_bfloat16 smem[];
