        if (kCopy == 0) { asm volatile(\"cp.async.commit_group;\\n\" ::); asm volatile(\"cp.async.commit_group;\\n\" ::); }
        else { cpa_tile(k + (size_t)(base + s * kBlockN) * kKVRowStride, st + s * kStageB, tid);
