               else asm volatile(\"cp.async.commit_group;\\n\" ::); }
    }
    __syncthreads();
    for (int j = 0; j < niter; ++j) {
        asm volatile(\"cp.async.wait_group 2;\\n\" ::);
        __syncthreads();
        const char* kt = st + (j % kStages) * kStageB;
        acc += (float)*reinterpret_cast<const __nv_bfloat16*>(kt + (tid & 1023) * 2);
        asm volatile(\"wgmma.wait_group.sync.aligned 1;\\n\" ::);
        __syncthreads();
        const int pf = j + kStages - 1;
        if (pf < niter) {
            const int t0 = (base + pf * kBlockN) % (ntile - kBlockN);
            cpa_tile(k + (size_t)t0 * kKVRowStride, st + (pf % kStages) * kStageB, tid);
            if (kCopy > 1) cpa_tile(v + (size_t)t0 * kKVRowStride, st + (pf % kStages) * kStageB + kTileB, tid);
            else asm volatile(\"cp.async.commit_group;\\n\" ::);
        } else {
            asm volatile(\"cp.async.commit_group;\\n\" ::);
            if (kCopy > 1) asm volatile(\"cp.async.commit_group;\\n\" ::);
        }
        asm volatile(\"wgmma.wait_group.sync.aligned 0;\\n\" ::);
        __syncthreads();
    }
    if (acc == 12345.678f) out[threadIdx.x] = acc;
}

template <int kCopy>
float run(const __nv_bfloat16* k, const __nv_bfloat16* v, int ntile, int niter, float* out, int grid) {
    cudaFuncSetAttribute(bench<kCopy>, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemB);
    bench<kCopy><<<grid, kThreads, kSmemB>>>(k, v, ntile, niter, out);
    cudaDeviceSynchronize();
    cudaEvent_t a, b;
    cudaEventCreate(&a); cudaEventCreate(&b);
    float best = 1e9f;
    for (int r = 0; r < 10; ++r) {
        cudaEventRecord(a);
        bench<kCopy><<<grid, kThreads, kSmemB>>>(k, v, ntile, niter, out);
        cudaEventRecord(b);
        cudaEventSynchronize(b);
        float ms; cudaEventElapsedTime(&ms, a, b);
        best = ms < best ? ms : best;
    }
    return best;
}

