    cudaMemset(hk, 0, nk * 2); cudaMemset(hv, 0, nk * 2);
    const double mb = (double)grid * niter * 65536 / (1 << 20);
    printf(\"copies=none : %.3f ms\\n\", run<0>(hk, hv, ntile, niter, out, grid));
