constexpr int kDim = 128, kHeadsKV = 8, kBlockN = 128, kThreads = 256, kStages = 3;
constexpr int kKVRowStride = kHeadsKV * kDim;
constexpr int kLboB = 144, kSboB = (kDim / 8) * kLboB;
constexpr int kTileB = (kBlockN / 8) * kSboB, kStageB = 2 * kTileB, kSmemB = kStages * kStageB;

__device__ __forceinline__ void cpa16(void* dst, const void* src) {
    uint32_t d = (uint32_t)__cvta_generic_to_shared(dst);
    asm volatile(\"cp.async.ca.shared.global [%0], [%1], 16;\\n\" ::\"r\"(d), \"l\"(src));
}

// Copy NC chunks (16 B each) per thread from source rows into the core-matrix layout.
template <int NC>
__device__ __forceinline__ void copy_n(const char* g, char* dst, int tid) {
    const int blk = tid >> 4, chunk = tid & 15;
    const char* gb = g + (size_t)blk * (8 * kKVRowStride * 2) + chunk * 16;
    char* db = dst + blk * kSboB + chunk * kLboB;
#pragma unroll
    for (int r = 0; r < NC; ++r) cpa16(db + r * 16, gb + (size_t)r * (kKVRowStride * 2) * 8);
}

// kMode 0: cp.async; 1: ld.global.v4 + st.shared.v4
template <int NC, int kMode>
__global__ void __launch_bounds__(kThreads, 1) bench(const __nv_bfloat16* __restrict__ k,
                                                     const __nv_bfloat16* __restrict__ v,
