            if (kMode == 0) {
                copy_n<NC>(gk, pd, tid);
                asm volatile(\"cp.async.commit_group;\\n\" ::);
                copy_n<NC>(gv, pd + kTileB, tid);
                asm volatile(\"cp.async.commit_group;\\n\" ::);
            } else {
                copy_n<NC>(gk, pd, tid);
                asm volatile(\"cp.async.commit_group;\\n\" ::);
                copy_n<NC>(gv, pd + kTileB, tid);
                asm volatile(\"cp.async.commit_group;\\n\" ::);
            }
        } else {
            asm volatile(\"cp.async.commit_group;\\n\" ::);
            asm volatile(\"cp.async.commit_group;\\n\" ::);
        }
        asm volatile(\"wgmma.wait_group.sync.aligned 0;\\n\" ::);
        __syncthreads();
    }
    if (acc == 12345.678f) out[tid] = acc;
}

